#include <bits/stdc++.h>
using namespace std; using U=uint64_t;int pc(U x){return __builtin_popcountll(x);}int low(U x){return __builtin_ctzll(x);}const U ALL=(1ULL<<57)-1;
int main(int argc,char**argv){ifstream f(argv[1]);int n,m;f>>n>>m;U a[57]={},C=0,I=0,E;vector<pair<int,int>>ed;for(int u,v;f>>u>>v;){a[u]|=1ULL<<v;a[v]|=1ULL<<u;ed.push_back({u,v});}for(int v=0;v<57;v++)if(pc(a[v])==7)C|=1ULL<<v;for(int v=0;v<57;v++)if(!(C>>v&1)&&!(a[v]&C))I|=1ULL<<v;E=ALL^C^I;vector<U>T;for(auto[u,v]:ed)if((I>>u&1)&&(I>>v&1))for(int w=v+1;w<57;w++)if((I>>w&1)&&(a[u]>>w&1)&&(a[v]>>w&1))T.push_back((1ULL<<u)|(1ULL<<v)|(1ULL<<w));long long nodes=0,dominating=0,feasible=0;int fam=0;array<int,6>ix;
function<void(int,int)>outer=[&](int k,int st){if(k<6){for(int q=st;q<=14-(6-k);q++){ix[k]=q;outer(k+1,q+1);}return;}U cover=0;for(int q:ix)cover|=T[q];if(pc(cover)!=18)return;fam++;U M=I&~cover;assert(find(T.begin(),T.end(),M)!=T.end());vector<U>groups;for(int q:ix)groups.push_back(T[q]);for(U z=M;z;z&=z-1){int v=low(z);groups.push_back((1ULL<<v)|(a[v]&E));}U allowed=C;int gid[57];fill(gid,gid+57,-1);for(int q=0;q<9;q++){assert(!(allowed&groups[q]));allowed|=groups[q];for(U z=groups[q];z;z&=z-1)gid[low(z)]=q;}assert(pc(allowed)==41);
function<void(U,U,U,int)>dfs=[&](U S,U avail,U covered,int depth){nodes++;if(depth==8){if(covered!=ALL)return;dominating++;bool good=true;for(U g:groups){U x=S&g;if(pc(x)!=1)continue;int v=low(x);bool works=false;for(U partners=a[v]&g;partners;partners&=partners-1){int w=low(partners);if(pc(a[w]&S)>=2){works=true;break;}}if(!works){good=false;break;}}if(good){feasible++;if(feasible<4)cout<<"FEASIBLE family="<<fam<<" S="<<S<<"\n";}return;}
if(pc(avail)<8-depth)return;U unc=ALL&~covered;vector<int>gains;for(U z=avail;z;z&=z-1){int v=low(z);gains.push_back(pc((a[v]|(1ULL<<v))&unc));}sort(gains.rbegin(),gains.rend());int bound=0;for(int i=0;i<8-depth;i++)bound+=gains[i];if(bound<pc(unc))return;
U choices=avail;if(unc){int best=58;for(U z=unc;z;z&=z-1){int u=low(z);U d=(a[u]|(1ULL<<u))&avail;int cnt=pc(d);if(cnt<best){best=cnt;choices=d;if(!cnt)return;}}}
while(choices){int v=low(choices);U bit=1ULL<<v;choices&=choices-1;avail&=~bit;U next=avail;int g=gid[v];if(g>=0){U old=S&groups[g];if(old)next&=~groups[g];else next&=~(groups[g]&~a[v]);}dfs(S|bit,next,covered|a[v]|bit,depth+1);}
};long long before=nodes,bd=dominating,bf=feasible;dfs(0,allowed,0,0);cout<<"family="<<fam<<" nodes="<<nodes-before<<" dominating="<<dominating-bd<<" feasible="<<feasible-bf<<"\n"<<flush;
};outer(0,0);cout<<"TOTAL families="<<fam<<" nodes="<<nodes<<" dominating="<<dominating<<" feasible="<<feasible<<"\n";}
